export const BASE_CSS = ":root {\n  --md-bg: #ffffff;\n  --md-text: #1f2937;\n  --md-muted: #667085;\n  --md-surface: #f8fafc;\n  --md-border: #cbd5e1;\n  --md-accent: #0f766e;\n  --md-focus: #f59e0b;\n}\n:root[data-mdhtml-theme=\"light\"] {\n  --md-bg: #ffffff;\n  --md-text: #1f2937;\n  --md-muted: #667085;\n  --md-surface: #f8fafc;\n  --md-border: #cbd5e1;\n  --md-accent: #0f766e;\n  --md-focus: #f59e0b;\n}\n:root[data-mdhtml-theme=\"dark\"] {\n  --md-bg: #0f172a;\n  --md-text: #f8fafc;\n  --md-muted: #cbd5e1;\n  --md-surface: #1e293b;\n  --md-border: #475569;\n  --md-accent: #5eead4;\n  --md-focus: #fbbf24;\n}\n:root[data-mdhtml-theme=\"system\"] {\n  --md-bg: #ffffff;\n  --md-text: #1f2937;\n  --md-muted: #667085;\n  --md-surface: #f8fafc;\n  --md-border: #cbd5e1;\n  --md-accent: #0f766e;\n  --md-focus: #f59e0b;\n}\n@media (prefers-color-scheme: dark) {\n  :root[data-mdhtml-theme=\"system\"] {\n    --md-bg: #0f172a;\n    --md-text: #f8fafc;\n    --md-muted: #cbd5e1;\n    --md-surface: #1e293b;\n    --md-border: #475569;\n    --md-accent: #5eead4;\n    --md-focus: #fbbf24;\n  }\n}\n\n* { box-sizing: border-box; }\nhtml { background: var(--md-bg); color: var(--md-text); scroll-behavior: smooth; }\nbody {\n  margin: 0;\n  background: var(--md-bg);\n  color: var(--md-text);\n  font-family: var(--md-font-body);\n  font-size: 1rem;\n  line-height: calc(1.5 * var(--md-density));\n}\n#mdhtml-app {\n  width: min(calc(100% - 3rem), var(--md-measure));\n  max-width: var(--md-measure);\n  margin: 0 auto;\n  padding: 4rem 0 6rem;\n  overflow: hidden;\n}\nh1, h2, h3, h4, h5, h6 {\n  margin: 2.2em 0 0.55em;\n  color: var(--md-text);\n  font-weight: 700;\n  line-height: 1.08;\n  letter-spacing: -0.025em;\n}\nh1 { font-size: clamp(2.25rem, 6vw, 3.8rem); }\nh2 { font-size: clamp(1.8rem, 4vw, 2.7rem); }\nh3 { font-size: clamp(1.4rem, 3vw, 2rem); }\nh4 { font-size: 1.35rem; }\nh5 { font-size: 1.15rem; }\nh6 { font-size: 1rem; letter-spacing: 0; }\np, ul, ol, dl, table, blockquote, pre, figure { margin: 1rem 0; }\na { color: var(--md-accent); text-decoration-thickness: 0.08em; text-underline-offset: 0.15em; }\na:hover { text-decoration-thickness: 0.14em; }\ncode, pre { font-family: var(--md-font-mono); }\ncode { padding: 0.12em 0.3em; border: 1px solid var(--md-border); border-radius: 0.25em; background: var(--md-surface); font-size: 0.9em; }\npre { overflow: auto; padding: 1rem; border: 1px solid var(--md-border); border-radius: var(--md-radius); background: var(--md-surface); line-height: 1.45; }\npre code { padding: 0; border: 0; background: transparent; }\nblockquote { margin-left: 0; padding: 0.25rem 1.25rem; border-left: 0.25rem solid var(--md-accent); color: var(--md-muted); }\nblockquote > :first-child { margin-top: 0; }\nblockquote > :last-child { margin-bottom: 0; }\nhr { margin: 2.5rem 0; border: 0; border-top: 1px solid var(--md-border); }\ntable { width: 100%; border-collapse: collapse; font-variant-numeric: tabular-nums; }\nth, td { padding: 0.7rem 0.8rem; border-bottom: 1px solid var(--md-border); text-align: left; vertical-align: top; }\nth { color: var(--md-muted); font-size: 0.85em; letter-spacing: 0.04em; text-transform: uppercase; }\nimg { max-width: 100%; height: auto; }\n\n#mdhtml-toolbar, #mdhtml-toc {\n  display: flex;\n  gap: 0.5rem;\n  align-items: center;\n  padding: 0.65rem 1rem;\n  background: var(--md-surface);\n  border: 1px solid var(--md-border);\n  color: var(--md-text);\n}\n#mdhtml-toolbar { position: sticky; z-index: 2; top: 0; justify-content: center; }\n#mdhtml-toolbar button, #mdhtml-toolbar select, #mdhtml-toc a { color: var(--md-accent); }\n#mdhtml-toolbar button, #mdhtml-toolbar select { padding: 0.35rem 0.55rem; border: 1px solid var(--md-border); border-radius: var(--md-radius); background: var(--md-bg); }\n#mdhtml-toc { margin: 1rem auto; width: min(calc(100% - 3rem), var(--md-measure)); }\n#mdhtml-toc ul { display: flex; flex-wrap: wrap; gap: 0.35rem 1rem; margin: 0; padding-left: 1.2rem; }\n\n.md-callout, .md-quote, .md-details, .md-stats, .md-bars, .md-kv, .md-timeline, .md-cards, .md-grid-item {\n  margin: 1.5rem 0;\n  padding: 1rem 1.15rem;\n  border: 1px solid var(--md-border);\n  border-radius: var(--md-radius);\n  background: var(--md-surface);\n  box-shadow: var(--md-shadow);\n}\n.md-callout { border-left: 0.3rem solid var(--md-accent); }\n.md-callout-badge { display: block; margin-bottom: 0.45rem; color: var(--md-accent); font-size: 0.78rem; font-weight: 700; letter-spacing: 0.08em; text-transform: uppercase; }\n.md-quote { padding: 0; background: transparent; border-width: 0 0 0 0.3rem; box-shadow: none; }\n.md-quote blockquote { margin: 0; border-left: 0; padding-left: 1rem; }\n.md-quote figcaption { margin: 0.5rem 0 0 1rem; color: var(--md-muted); }\n.md-columns { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 16rem), 1fr)); gap: 1rem; margin: 1.5rem 0; }\n.md-column > :first-child { margin-top: 0; }\n.md-column > :last-child { margin-bottom: 0; }\n.md-details { padding: 0.8rem 1rem; }\n.md-details summary { cursor: pointer; color: var(--md-accent); font-weight: 700; }\n.md-details[open] summary { margin-bottom: 0.75rem; }\n.md-stats, .md-bars, .md-kv { overflow: auto; }\n.md-kv { display: grid; grid-template-columns: minmax(7rem, 0.5fr) 1fr; gap: 0; }\n.md-kv dt, .md-kv dd { margin: 0; padding: 0.65rem 0; border-bottom: 1px solid var(--md-border); }\n.md-kv dt { color: var(--md-muted); font-weight: 700; }\n.md-kv dd { padding-left: 1rem; }\n.md-steps, .md-timeline { padding-left: 2rem; }\n.md-steps li, .md-timeline li { padding: 0.35rem 0; }\n.md-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 15rem), 1fr)); gap: 1rem; margin: 1.5rem 0; }\n.md-grid-item { margin: 0; }\n.md-grid-item > :first-child { margin-top: 0; }\n.md-grid-item > :last-child { margin-bottom: 0; }\n.md-gallery { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 12rem), 1fr)); gap: 1rem; margin: 1.5rem 0; }\n.md-gallery-item { margin: 0; }\n.md-gallery-item img { display: block; width: 100%; border-radius: var(--md-radius); }\n.md-hero { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 0.8fr); gap: 2rem; align-items: center; margin: 2rem 0; }\n.md-hero-content > :first-child { margin-top: 0; }\n.md-hero-media img { display: block; width: 100%; border-radius: var(--md-radius); }\n\n:focus-visible { outline: 3px solid var(--md-focus); outline-offset: 2px; }\n#mdhtml-source-view { max-width: min(90vw, 72rem); max-height: 85vh; padding: 1rem; border: 1px solid var(--md-border); background: var(--md-surface); color: var(--md-text); }\n#mdhtml-source-view pre { max-height: 70vh; }\n#mdhtml-lightbox { max-width: min(90vw, 72rem); max-height: 90vh; padding: 1rem; border: 1px solid var(--md-border); background: var(--md-surface); color: var(--md-text); }\n#mdhtml-lightbox img { display: block; max-width: 80vw; max-height: 75vh; object-fit: contain; }\n#mdhtml-lightbox [data-md-lightbox-counter] { display: block; margin: 0.75rem 0; }\n#mdhtml-lightbox[data-md-reduced-motion] { animation: none; transition: none; scroll-behavior: auto; }\n@media (max-width: 42rem) {\n  #mdhtml-app { width: min(calc(100% - 2rem), var(--md-measure)); padding-top: 2.5rem; }\n  .md-hero { grid-template-columns: 1fr; }\n  #mdhtml-toolbar { position: static; flex-wrap: wrap; }\n}\n@media (prefers-reduced-motion: reduce) {\n  #mdhtml-lightbox { animation: none; transition: none; scroll-behavior: auto; }\n  html { scroll-behavior: auto; }\n}\n@media print {\n  #mdhtml-toolbar, #mdhtml-toc, #mdhtml-source-view { display: none !important; }\n  #mdhtml-app { width: auto; max-width: none; overflow: visible; padding: 0; }\n  html, body { background: #fff; color: #000; }\n  a { color: #000; }\n  .md-callout, .md-quote, .md-details, .md-stats, .md-bars, .md-kv, .md-timeline, .md-cards, .md-grid-item { box-shadow: none; }\n}\n";
export const TECHNICAL_CSS = ":root {\n  --md-font-body: \"Instrument Sans\", system-ui, sans-serif;\n  --md-font-mono: \"Geist Mono\", ui-monospace, monospace;\n  --md-measure: 78ch;\n  --md-density: 0.88;\n  --md-heading-scale: 1.18;\n  --md-radius: 0.5rem;\n  --md-shadow: 0 1px 2px rgb(15 23 42 / 0.08);\n}\n";
export const EDITORIAL_CSS = ":root {\n  --md-font-body: \"Newsreader\", Georgia, serif;\n  --md-font-mono: \"Geist Mono\", ui-monospace, monospace;\n  --md-measure: 68ch;\n  --md-density: 1;\n  --md-heading-scale: 1.25;\n  --md-radius: 0.25rem;\n  --md-shadow: 0 2px 10px rgb(57 45 35 / 0.12);\n}\n";
